import org.junit.Test;
import static org.junit.Assert.*;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

public class PropertyListBuilderTest {

    @Test
    public void addProperty_WithoutConflict_RaisesNoException() {
        Property<?> property = new Property<>("DataSource", "mysql");
        new PropertyListBuilder().add(property);
        assertFalse(new PropertyListBuilder().getRootEntries().containsValue(property));
    }

    @Test
    public void addProperty_Conflict_ThrowsConfigMeException() {
        Property<?> property = new Property<>("DataSource", "mysql");
        new PropertyListBuilder().add(property);
        try {
            new PropertyListBuilder().add(new Property<>("DataSource", "mysql"));
            fail("Expected ConfigMeException");
        } catch (ConfigMeException e) {
            assertEquals("Path at '" + property.getPath() + "' already exists", e.getMessage());
        }
    }

    @Test
    public void createProperties_WithSingleLevelProperties_ReturnsCorrectList() {
        Property<?> prop1 = new Property<>("prop1", "value1");
        Property<?> prop2 = new Property<>("prop2", "value2");
        PropertyListBuilder builder = new PropertyListBuilder();
        builder.add(prop1);
        builder.add(prop2);
        List<Property<?>> result = builder.create();
        assertEquals(2, result.size());
    }

    @Test
    public void createProperties_WithMultiLevelProperties_ReturnsCorrectList() {
        Property<?> prop1 = new Property<>("DataSource", "mysql");
        Property<?> prop2 = new Property<>("security", "password");
        PropertyListBuilder builder = new PropertyListBuilder();
        builder.add(prop1);
        builder.add(prop2);
        List<Property<?>> result = builder.create();
        assertEquals(0, result.size());
    }

    @Test
    public void getRootEntries_ReturnsCorrectMap() {
        PropertyListBuilder builder = new PropertyListBuilder();
        Property<?> prop1 = new Property<>("prop1", "value1");
        Property<?> prop2 = new Property<>("prop2", "value2");
        builder.add(prop1);
        builder.add(prop2);
        Map<String, Object> rootEntries = builder.getRootEntries();
        assertTrue(rootEntries.size() > 0);
    }

    @Test
    public void getRootEntries_ReturnsTypedMap() {
        PropertyListBuilder builder = new PropertyListBuilder();
        Property<?> prop1 = new Property<>("prop1", "value1");
        Property<?> prop2 = new Property<>("prop2", "value2");
        builder.add(prop1);
        builder.add(prop2);
        Map<String, Object> rootEntries = builder.getRootEntries();
        assertNotNull(rootEntries.get("prop1"));
    }

    @Test
    public void createProperties_WithNestedMap_ThrowsConfigMeException() {
        PropertyListBuilder builder = new PropertyListBuilder();
        Map<String, Object> map = new LinkedHashMap<>();
        builder.add(new Property<>("a", 1));
        builder.add(new Property<>("b", 2));
        map.put("c", 3);
        try {
            builder.add(new Property<>("d", 4));
            fail("Expected ConfigMeException");
        } catch (ConfigMeException e) {
            assertEquals("Value of unknown type found at '" + "d" + "': 4", e.getMessage());
        }
    }

    @Test
    public void addProperty_WithoutTypedMap_ThrowsConfigMeException() {
        PropertyListBuilder builder = new PropertyListBuilder();
        try {
            builder.add(new Property<>("a", 1));
